import React, { useState, useEffect } from 'react';
import Papa from 'papaparse';
import './RiverDashboard.css';

// --- CONFIGURATION ---
const BACKEND_URL = 'http://127.0.0.1:8000'; // Your Django URL
const API_ENDPOINT = '/api/s3-presign/';    // Must match urls.py

// Exact filenames in your S3 bucket
const CSV_FILENAME = 'forecast_outputs.csv';
const TXT_FILENAME = 'lime_short_sentences.txt';

const RiverDashboard = () => {
    const [chartData, setChartData] = useState([]);
    const [limeSentences, setLimeSentences] = useState([]);
    const [loading, setLoading] = useState(true);
    const [lastUpdated, setLastUpdated] = useState(null);

    // Function to get the signed URL from Django
    const getSignedUrl = async (fileName) => {
        try {
            const res = await fetch(`${BACKEND_URL}${API_ENDPOINT}?file=${fileName}`);
            const data = await res.json();
            if (data.url) return data.url;
            throw new Error(data.error || 'Failed to get URL');
        } catch (error) {
            console.error(`Error getting URL for ${fileName}:`, error);
            return null;
        }
    };

    const fetchData = async () => {
        setLoading(true);
        console.log("🔄 Fetching latest data from AWS...");

        try {
            // 1. Get secure S3 links from Backend
            const csvUrl = await getSignedUrl(CSV_FILENAME);
            const txtUrl = await getSignedUrl(TXT_FILENAME);

            if (!csvUrl || !txtUrl) throw new Error("Could not retrieve file URLs");

            // 2. Cache Busting: Add timestamp to force fresh download
            const timestamp = new Date().getTime(); 
            const freshCsvUrl = `${csvUrl}&t=${timestamp}`;
            const freshTxtUrl = `${txtUrl}&t=${timestamp}`;

            // 3. Fetch and Parse CSV
            const csvRes = await fetch(freshCsvUrl);
            const csvText = await csvRes.text();
            
            Papa.parse(csvText, {
                header: true,
                skipEmptyLines: true,
                complete: (result) => {
                    const data = result.data.map(row => ({
                        time: row.Timestamp, 
                        level: parseFloat(row.Predicted_Water_Level)
                    }));
                    setChartData(data);
                }
            });

            // 4. Fetch and Parse Text
            const txtRes = await fetch(freshTxtUrl);
            const txtText = await txtRes.text();
            setLimeSentences(txtText.split('\n').filter(line => line.trim() !== ''));

            setLastUpdated(new Date().toLocaleTimeString());

        } catch (error) {
            console.error("❌ Data Fetch Error:", error);
        } finally {
            setLoading(false);
        }
    };

    // Auto-refresh logic
    useEffect(() => {
        fetchData(); // Initial load

        // Poll every 10 minutes (600,000ms) to ensure hourly updates are caught
        const interval = setInterval(fetchData, 600000);
        return () => clearInterval(interval);
    }, []);

    return (
        <div className="dashboard-container">
            <h1>River Water Level Forecast</h1>
            
            <div className="status-bar">
                {loading ? (
                    <span style={{color: 'orange'}}>⏳ Syncing...</span>
                ) : (
                    <span style={{color: 'green'}}>✅ Live Data (Updated: {lastUpdated})</span>
                )}
                <button onClick={fetchData} style={{marginLeft: '15px', cursor: 'pointer'}}>
                    🔄 Refresh Now
                </button>
            </div>

            {/* Visualize Data */}
            <div className="content-grid">
                <div className="card">
                    <h2>Forecast Data</h2>
                    {chartData.length > 0 ? (
                        <ul>
                            {chartData.slice(0, 5).map((d, i) => (
                                <li key={i}>{d.time}: <strong>{d.level.toFixed(2)}m</strong></li>
                            ))}
                        </ul>
                    ) : <p>No data available</p>}
                </div>

                <div className="card">
                    <h2>AI Explanations</h2>
                    {limeSentences.map((line, i) => (
                        <div key={i} className="lime-item">{line}</div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default RiverDashboard;
